export function buildEquipmentAndItemsLibraryEntries(): LibraryEntry[] {
  const mundane = [...SRD_WEAPONS_AND_ARMOR, ...SRD_ADVENTURING_GEAR_AND_TOOLS, ...SRD_EXTRA_EQUIPMENT_AND_SERVICES];
  const magic = [...SRD_MAGIC_ITEMS];

  const formatEntry = (item: SrdItemRaw, isMagic: boolean): LibraryEntry => {
    const metaLines: string[] = [];
    if (item.rarity || isMagic) {
      metaLines.push(`${item.type}, ${item.rarity || 'Uncommon'}${item.attunement ? ` (${item.attunement})` : ''}`);
    } else {
      metaLines.push(`${item.type}${item.cost ? ` · Cost: ${item.cost}` : ''}${item.weight ? ` · Weight: ${item.weight}` : ''}`);
    }
    if (item.damage) metaLines.push(`Damage: ${item.damage}${item.damageType ? ` ${item.damageType}` : ''}`);
    if (item.ac) metaLines.push(`Armor Class: ${item.ac}`);
    if (item.properties) metaLines.push(`Properties: ${item.properties}`);
    if (item.mastery) metaLines.push(`Weapon Mastery: ${item.mastery}`);

    const cleanRarity = item.rarity
      ? item.rarity.includes('Common')
        ? 'Common'
        : item.rarity.includes('Uncommon')
        ? 'Uncommon'
        : item.rarity.includes('Very Rare')
        ? 'Very Rare'
        : item.rarity.includes('Rare')
        ? 'Rare'
        : item.rarity.includes('Legendary')
        ? 'Legendary'
        : item.rarity.includes('Artifact')
        ? 'Artifact'
        : item.rarity
      : 'Common';

    const category = isMagic ? 'magic_items' : 'equipment';

    return {
      id: `srd_${category}_${item.name.toLowerCase().replace(/[^a-z0-9]+/g, '_')}`,
      name: item.name,
      category,
      source: 'SRD 5.2.1',
      summary: `${metaLines[0]} — ${item.desc.slice(0, 140)}${item.desc.length > 140 ? '...' : ''}`,
      content: `${metaLines.join('\n')}\n\n${item.desc}`,
      stats: {
        rarity: cleanRarity,
        itemType: item.type,
        attunement: Boolean(item.attunement),
        damage: item.damage,
        damageType: item.damageType,
        healing: item.healing,
        ac: item.ac,
        cost: item.cost,
        weight: item.weight,
        mastery: item.mastery,
        properties: item.properties,
      },
      tags: [
        'Item',
        item.type.split('(')[0].trim(),
        ...(isMagic ? [cleanRarity, 'Magic Item'] : ['Equipment', 'Common']),
        ...(item.attunement ? ['Attunement'] : []),
        ...(item.mastery ? [`Mastery: ${item.mastery}`, item.mastery] : []),
      ],
    };
  };

  return [
    ...mundane.map(i => formatEntry(i, false)),
    ...magic.map(i => formatEntry(i, true)),
  ];
}

